import{_ as n,o as a,c as r,ah as t}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Financer des apprenants","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/entreprises/financeur.md","filePath":"src/guide/entreprises/financeur.md"}'),s={name:"guide/entreprises/financeur.md"};function o(i,e,p,l,c,u){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="financer-des-apprenants" tabindex="-1">Financer des apprenants <a class="header-anchor" href="#financer-des-apprenants" aria-label="Permalink to &quot;Financer des apprenants&quot;">​</a></h1><p>Une entreprise ou une structure peut prendre en charge tout ou partie de la formation d&#39;un apprenant. Le rôle <strong>Financeur</strong> lui donne un espace dédié, <strong>Parcours → Apprenants financés</strong>.</p><h2 id="obtenir-le-role-financeur" tabindex="-1">Obtenir le rôle Financeur <a class="header-anchor" href="#obtenir-le-role-financeur" aria-label="Permalink to &quot;Obtenir le rôle Financeur&quot;">​</a></h2><p>Le rôle exige un <strong>compte organisation</strong> : si votre compte est un compte individu, <a href="./../premiers-pas.html#compte-individu-ou-compte-organisation">transformez-le d&#39;abord</a>. Demandez ensuite le rôle <strong>Financeur</strong> dans <strong>Paramètres → Rôles</strong>. La demande est examinée par le Chargé de partenariats, qui vous prévient par e-mail de sa décision.</p><h2 id="comment-un-financement-demarre" tabindex="-1">Comment un financement démarre <a class="header-anchor" href="#comment-un-financement-demarre" aria-label="Permalink to &quot;Comment un financement démarre&quot;">​</a></h2><p>Le financement se décide <strong>avec l&#39;apprenant, avant la signature</strong> de sa convention. Le Coordinateur pédagogique désigne votre compte comme financeur et fixe votre part, de 1 à 100 %.</p><p>À partir de là :</p><ul><li>la <strong>répartition</strong> figure sur la convention de formation (par exemple 60 % pour l&#39;apprenant, 40 % pour vous) ;</li><li>chaque échéance est facturée <strong>en deux factures distinctes</strong>, une par payeur, chacune suivie séparément ;</li><li>si vous financez 100 %, l&#39;apprenant n&#39;a rien à payer.</li></ul><h2 id="votre-espace-«-apprenants-finances-»" tabindex="-1">Votre espace « Apprenants financés » <a class="header-anchor" href="#votre-espace-«-apprenants-finances-»" aria-label="Permalink to &quot;Votre espace « Apprenants financés »&quot;">​</a></h2><p>Vous y voyez <strong>uniquement les apprenants que vous financez</strong> : leur formation, leur cohorte, leur statut et <strong>votre part</strong>, ainsi que les <strong>factures de votre part</strong>. Vous ne voyez ni les autres financeurs ni les factures de l&#39;apprenant.</p><p>Les factures vous sont aussi envoyées en PDF par e-mail, et rangées dans <strong>Mes documents</strong>.</p><h2 id="signer-la-convention-tripartite" tabindex="-1">Signer la convention tripartite <a class="header-anchor" href="#signer-la-convention-tripartite" aria-label="Permalink to &quot;Signer la convention tripartite&quot;">​</a></h2><p>Quand la convention de l&#39;apprenant est contre-signée par edPage group, une <strong>convention tripartite de financement</strong> est préparée à votre intention. Elle reprend les mentions de la convention : les parties, la formation, la cohorte, le prix, votre part et l&#39;échéancier.</p><p>Pour la signer, depuis <strong>Apprenants financés</strong> :</p><ol><li>ouvrez la convention tripartite de l&#39;apprenant ;</li><li>faites défiler jusqu&#39;au bout et cochez « J&#39;ai lu la convention jusqu&#39;au bout et j&#39;en accepte les termes » ;</li><li>demandez le code : un code à <strong>6 chiffres</strong> est envoyé à votre adresse e-mail, valable <strong>15 minutes</strong>, utilisable une fois, avec 5 essais ;</li><li>saisissez-le et signez.</li></ol><p>edPage group contre-signe ensuite. Le PDF scellé (<code>CONVT-NB-AAAA-XXX</code>) est envoyé à vous et à l&#39;apprenant.</p><p>Cette convention <strong>ne retarde ni l&#39;inscription ni la facturation</strong> : elles reposent déjà sur la convention de l&#39;apprenant. Si l&#39;apprenant change de cohorte, la tripartite est remplacée avec sa convention, et une nouvelle vous est proposée.</p><h2 id="les-retards-de-paiement" tabindex="-1">Les retards de paiement <a class="header-anchor" href="#les-retards-de-paiement" aria-label="Permalink to &quot;Les retards de paiement&quot;">​</a></h2><p>Les rappels et la chronologie d&#39;un impayé sont ceux de toute facture : rappels 15, 7 et 1 jours avant l&#39;échéance, rappel le lendemain, relance du Coordinateur à J+7, retard et moratoire de 15 jours à J+15, suspension à J+30.</p><p><strong>Si votre part est en retard, l&#39;accès de l&#39;apprenant à Sève est suspendu</strong>, même s&#39;il a réglé la sienne. Il est rétabli dès que vous payez.</p><p>Le solde de la formation doit être payé, par l&#39;apprenant <strong>et</strong> par vous, pour que le certificat soit délivré.</p>',21)])])}const g=n(s,[["render",o]]);export{m as __pageData,g as default};
